                'filename_s': Cover.get_cover_url(cover_id, size='s', ext=ext),
                'filename_m': Cover.get_cover_url(cover_id, size='m', ext=ext),
                'filename_l': Cover.get_cover_url(cover_id, size='l', ext=ext),
            }
            covers_db.update(
                'cover',
                where='id=$cover_id and archived=$true and failed=$false',
                uploaded=True,
                vars={
                    'cover_id': cover_id,
                    'true': True,
                    'false': False,
                },
                **filenames,
            )
            updated += 1
        return updated


class Uploader:
    """Small wrapper around the Internet Archive command line client."""

    @staticmethod
    def upload(itemname, filepaths):
        command = ['ia', 'upload', itemname, *filepaths, '--retries', '10']
        try:
            return run(command, text=True, capture_output=True, check=True)
        except (OSError, CalledProcessError) as exc:
            log('upload failed', itemname, exc)
            return None

    @staticmethod
    def is_uploaded(item, zip_filename, verbose=False):
        """Check that a named ZIP appears in the Internet Archive item listing."""
        try:
            result = run(
                ['ia', 'list', item], text=True, capture_output=True, check=True
            )
        except (OSError, CalledProcessError) as exc:
            if verbose:
                log('unable to list archive item', item, exc)
            return False

        filename = os.path.basename(zip_filename)
        uploaded = any(
            token.rstrip('/').rsplit('/', 1)[-1] == filename
            for line in result.stdout.splitlines()
            for token in line.split()
        )
        if verbose:
            log(item, filename, 'uploaded' if uploaded else 'missing')
        return uploaded


def _zip_path_for_name(name):
    filename = os.path.basename(name)
    if filename != name:
        raise ValueError(f'Cover archive member names must be flat: {name!r}')
    match = _ZIP_NAME.fullmatch(filename)
    if not match:
        raise ValueError(f'Invalid cover archive member name: {name!r}')
    item_id, batch_id = Cover.id_to_item_and_batch_id(match.group('id'))
    size = (match.group('size') or '').lower()
    return Batch.get_abspath(item_id, batch_id, size), match.group('id')


def open_zipfile(name):
    """Open the designated batch ZIP for writing, creating its directory."""
    path, _cover_id = _zip_path_for_name(name)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    return zipfile.ZipFile(path, mode='a', compression=zipfile.ZIP_STORED)


def get_zipfile(name):
    """Return the open ZIP for a cover member, opening it when necessary."""
    path, _cover_id = _zip_path_for_name(name)
    archive = _zipfile_registry.get(path)
    if archive is None or archive.fp is None:
        archive = open_zipfile(name)
        _zipfile_registry[path] = archive
    return archive


class ZipManager:
    """Write uncompressed cover ZIPs and avoid duplicate members on retries."""

    def __init__(self):
        self.zipfiles = {}
        self.added_files = defaultdict(set)

    def add_file(self, name, filepath, mtime):
        path, _cover_id = _zip_path_for_name(name)
        archive = self.zipfiles.get(path)
        if archive is None or archive.fp is None:
            archive = get_zipfile(name)
            self.zipfiles[path] = archive
            self.added_files[path].update(archive.namelist())

        if name in self.added_files[path]:
            return f'{os.path.basename(path)}/{name}'

        if isinstance(mtime, datetime):
            timestamp = mtime.timestamp()
        else:
            timestamp = float(mtime)
        modified = datetime.fromtimestamp(timestamp)
        year = min(max(modified.year, 1980), 2107)
        date_time = (year, modified.month, modified.day, modified.hour, modified.minute, modified.second)
        info = zipfile.ZipInfo(name, date_time=date_time)
        info.compress_type = zipfile.ZIP_STORED
        info.external_attr = 0o100644 << 16
        with open(filepath, 'rb') as fileobj:
            archive.writestr(info, fileobj.read(), compress_type=zipfile.ZIP_STORED)
        self.added_files[path].add(name)
        return f'{os.path.basename(path)}/{name}'

    def close(self):
        for path, archive in self.zipfiles.items():
            if archive.fp is not None:
                archive.close()
            if _zipfile_registry.get(path) is archive:
                del _zipfile_registry[path]
        self.zipfiles.clear()
        self.added_files.clear()


@contextmanager
def _batch_lock(item_id, batch_id):
    """Take a non-blocking exclusive lock shared by archive and upload workers."""
    item_id, batch_id = _normalize_ids(item_id, batch_id)
    lock_dir = os.path.join(config.data_root, 'items', '.locks')
    os.makedirs(lock_dir, exist_ok=True)
    lock_path = os.path.join(lock_dir, f'covers_{item_id}_{batch_id}.lock')
    with open(lock_path, 'a+b') as lock_file:
        try:
            fcntl.flock(lock_file.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            yield False
            return
        try:
            yield True
        finally:
            fcntl.flock(lock_file.fileno(), fcntl.LOCK_UN)


def count_files_in_zip(filepath):
    """Return the number of JPEG images in a batch ZIP."""
    with zipfile.ZipFile(filepath) as archive:
        return sum(
            filename.lower().endswith('.jpg')
            for filename in archive.namelist()
            if not filename.endswith('/')
        )


def archive(test=True):
    """Package pending local covers into deterministic batch ZIP files."""
    covers_db = CoverDB()
    covers = covers_db.get_unarchived_covers()
    batches = defaultdict(list)
    for cover in covers:
        item_id, batch_id = Cover.id_to_item_and_batch_id(cover.id)
        batches[(item_id, batch_id)].append(cover)

    for (item_id, batch_id), _selected in sorted(batches.items()):
        with _batch_lock(item_id, batch_id) as locked:
            if not locked:
                log('batch is already being archived', item_id, batch_id)
                continue

            pending = covers_db.get_pending_batch(item_id, batch_id)
            zip_manager = ZipManager()
            archived_ids = []
            failed_ids = []
            try:
                for row in pending:
                    cover = Cover(row)
                    if not cover.has_valid_files():
                        log('missing image file for', f'{int(cover.id):010d}')
                        failed_ids.append(cover.id)
                        continue

                    created = cover.created
                    if isinstance(created, str):
                        from infogami.infobase import utils

                        created = utils.parse_datetime(created)
                    timestamp = time.mktime(created.timetuple()) if created else 0
                    padded_id = f'{int(cover.id):010d}'
                    files = (
                        ('', 'filename', f'{padded_id}.jpg'),
                        ('s', 'filename_s', f'{padded_id}-S.jpg'),
                        ('m', 'filename_m', f'{padded_id}-M.jpg'),
                        ('l', 'filename_l', f'{padded_id}-L.jpg'),
                    )
                    for _size, field, member_name in files:
                        zip_manager.add_file(
                            member_name,
                            find_image_path(getattr(cover, field)),
                            timestamp,
                        )
                    archived_ids.append(cover.id)
            finally:
                zip_manager.close()

            if not test:
                for cover_id in archived_ids:
                    covers_db.mark_archived(cover_id)
                for cover_id in failed_ids:
                    covers_db.mark_failed(cover_id)


def audit(group_id, chunk_ids=(0, 100), sizes=SIZES) -> None:
    """Print which ZIP batches are missing from their Internet Archive items."""
    group_id = f'{int(group_id):04d}'
    scope = range(*(chunk_ids if isinstance(chunk_ids, tuple) else (0, chunk_ids)))
    for size in sizes:
        size = _normal_size(size)
        prefix = f'{size}_' if size else ''
        item = f'{prefix}covers_{group_id}'
        missing = []
        print(f"\n{size or 'full'}: ", end='')
        for batch_id in scope:
            filename = f'{item}_{batch_id:02d}.zip'
            if Uploader.is_uploaded(item, filename):
                print('.', end='', flush=True)
            else:
                print('X', end='', flush=True)
                missing.append(filename)
        print()
        if missing:
            print(f"ia upload {item} {' '.join(missing)} --retries 10")
        def redirect(id):
            size_part = size and ("-" + size) or ""
            url = f"/{category}/id/{id}{size_part}.jpg"

            if query := web.ctx.env.get('QUERY_STRING'):
                url += '?' + query
            raise web.found(url)

        if key == 'isbn':
            value = value.replace("-", "").strip()  # strip hyphens from ISBN
            value = self.query(category, key, value)
        elif key == 'ia':
            url = self.get_ia_cover_url(value, size)
            if url:
                raise web.found(url)
            else:
                value = None  # notfound or redirect to default. handled later.
        elif key != 'id':
            value = self.query(category, key, value)

        if not value or (value and safeint(value) in config.blocked_covers):
            return notfound()

        # redirect to archive.org cluster for large size and original images whenever possible
        if size in ("L", "") and self.is_cover_in_cluster(value):
            url = zipview_url_from_id(int(value), size)
            raise web.found(url)

        d = self.get_details(value, size.lower())
        if not d:
            return notfound()

        filename_field = 'filename_' + size.lower() if size else 'filename'
        archived_url = d.get(filename_field)
        if isinstance(archived_url, str) and archived_url.startswith(('http://', 'https://')):
            raise web.found(archived_url)

        # The 8M-era batch references point to legacy TAR files. Resolve those
        # records through the current ZIP layout while local, unuploaded covers
        # continue to be served from their source files.
        if isinstance(value, int) or value.isnumeric():  # noqa: SIM102
            if 8810000 > int(value) >= 8000000 and archived_url and '.tar:' in archived_url:
                raise web.found(
                    Cover.get_cover_url(int(value), size=size.lower(), protocol=web.ctx.protocol)
                )

        # set cache-for-ever headers only when requested with ID
        if key == 'id':
            etag = f"{d.id}-{size.lower()}"
            if not web.modified(trim_microsecond(d.created), etag=etag):
                raise web.notmodified()

            web.header('Cache-Control', 'public')
            # this image is not going to expire in next 100 years.
            web.expires(100 * 365 * 24 * 3600)
        else:
            web.header('Cache-Control', 'public')
            # Allow the client to cache the image for 10 mins to avoid further requests
            web.expires(10 * 60)

        web.header('Content-Type', 'image/jpeg')
        try:
            return read_image(d, size)
        except OSError:
            raise web.notfound()

    def get_ia_cover_url(self, identifier, size="M"):
        url = "https://archive.org/metadata/%s/metadata" % identifier
        try:
            d = requests.get(url).json().get("result", {})
        except (OSError, ValueError):
            return

        # Not a text item or no images or scan is not complete yet
        if (
            d.get("mediatype") != "texts"
            or d.get("repub_state", "4") not in ("4", "6")
            or "imagecount" not in d
        ):
            return

